/**
 * The Worker Cloudflare runs: OpenNext's generated Next.js handler, plus the cron trigger
 * (wrangler.jsonc) that sends abandoned-checkout reminders and runs product schedules and low-stock emails. The cron calls the app's own route, so the
 * check runs with the same code and settings as everything else.
 */
// Generated by `opennextjs-cloudflare build`, so it may not exist yet when type-checking
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";

// Just the shapes used here, so the app doesn't need the Workers runtime types
interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}
interface Ctx {
  waitUntil(p: Promise<unknown>): void;
}
interface NextHandler {
  fetch(req: Request, env: Env, ctx: Ctx): Response | Promise<Response>;
}
const next = handler as NextHandler;

const worker = {
  fetch: next.fetch,
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) return console.warn("[cron] CRON_SECRET isn't set, so checkout reminders, product schedules and stock emails don't run");
    // Each job is the app's own route, run with the same code and settings as everything else
    for (const job of ["abandoned", "catalog"]) {
      const req = new Request(`https://powerproof.internal/api/cron/${job}`, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
      ctx.waitUntil(
        Promise.resolve(next.fetch(req, env, ctx)).then(async (res) => {
          if (!res.ok) console.error(`[cron] ${job} answered`, res.status, await res.text().catch(() => ""));
        })
      );
    }
  },
};

export default worker;
